function validate([nums, numSlots]) {
  if (!Number.isInteger(numSlots) || numSlots < 1 || numSlots > 9) return 'numSlots is a whole number from 1 to 9.';
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 2 * numSlots) return 'nums needs 1 to 2 * numSlots values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 15)) return 'Each value of nums is a whole number from 1 to 15.';
  return null;
}

