function maximumANDSum(nums, numSlots) {
  const n = nums.length;
  const positions = 2 * numSlots;
  const full = 1 << positions;
  const ones = new Array(full).fill(0);
  const dp = new Array(full).fill(0);
  let best = 0;

  for (let mask = 1; mask < full; mask++) {
    ones[mask] = ones[mask >> 1] + (mask & 1);
    const i = ones[mask] - 1;
    if (i >= n) {
      continue;
    }
    for (let j = 0; j < positions; j++) {
      if (mask & (1 << j)) {
        const slot = (j >> 1) + 1;
        dp[mask] = Math.max(dp[mask], dp[mask ^ (1 << j)] + (nums[i] & slot));
      }
    }
    if (i === n - 1) {
      best = Math.max(best, dp[mask]);
    }
  }
  return best;
}

