function maximumANDSum(nums, numSlots) {
  // Top-down search over how full each slot is, remembered by a text key.
  const used = new Array(numSlots + 1).fill(0);
  const memo = new Map();
  const place = (k) => {
    if (k === nums.length) return 0;
    const key = used.join('');
    if (memo.has(key)) return memo.get(key);
    let top = -Infinity;
    for (let label = 1; label <= numSlots; label++) {
      if (used[label] === 2) continue;
      used[label]++;
      top = Math.max(top, (nums[k] & label) + place(k + 1));
      used[label]--;
    }
    memo.set(key, top);
    return top;
  };
  return place(0);
}

