function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    const numSlots = rand() < 0.75 ? 9 : int(6, 8);
    const n = rand() < 0.6 ? 2 * numSlots : int(1, 2 * numSlots);
    const top = rand() < 0.3 ? int(1, 4) : 15;
    return [Array.from({ length: n }, () => int(1, top)), numSlots];
  }
  const numSlots = int(1, 4);
  const n = int(1, 2 * numSlots);
  const top = rand() < 0.3 ? 3 : 15;
  return [Array.from({ length: n }, () => int(1, top)), numSlots];
}
